function validate([n, edges, values, k]) {
  if (!Number.isInteger(n) || n < 1 || n > 30000) return 'n is between 1 and 3 * 10^4.';
  if (!Array.isArray(edges) || edges.length !== n - 1) return 'edges must have exactly n - 1 entries.';
  if (!Array.isArray(values) || values.length !== n) return 'values must have exactly n entries.';
  if (values.some(v => !Number.isInteger(v) || v < 0 || v > 1000000000)) return 'Each value is an integer from 0 to 10^9.';
  if (!Number.isInteger(k) || k < 1 || k > 1000000000) return 'k is between 1 and 10^9.';
  const root = Array.from({ length: n }, (_, i) => i);
  const find = x => { while (root[x] !== x) { root[x] = root[root[x]]; x = root[x]; } return x; };
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 2) return 'Each edge is a pair [a, b].';
    const [a, b] = edge;
    if (!Number.isInteger(a) || !Number.isInteger(b) || a < 0 || b < 0 || a >= n || b >= n) return 'Edge endpoints are between 0 and n - 1.';
    const ra = find(a), rb = find(b);
    if (ra === rb) return 'edges must form a tree (no cycles or repeated edges).';
    root[ra] = rb;
  }
  if (values.reduce((s, v) => s + v, 0) % k !== 0) return 'The sum of values must be divisible by k.';
  return null;
}

