function maxKDivisibleComponents(n, edges, values, k) {
  const graph = Array.from({ length: n }, () => []);
  for (const [a, b] of edges) {
    graph[a].push(b);
    graph[b].push(a);
  }

  let components = 0;
  const dfs = (node, parent) => {
    let sum = values[node];
    for (const next of graph[node]) {
      if (next !== parent) {
        sum += dfs(next, node);
      }
    }
    if (sum % k === 0) {
      components++;
      return 0;
    }
    return sum % k;
  };

  dfs(0, -1);
  return components;
}

