function maxKDivisibleComponents(n, edges, values, k) {
  // Try every subset of edges to keep; label components with a simple flood and test each sum.
  let best = 0;
  for (let mask = 0; mask < (1 << edges.length); mask++) {
    const comp = new Array(n).fill(-1);
    let count = 0;
    for (let start = 0; start < n; start++) {
      if (comp[start] !== -1) continue;
      comp[start] = count;
      let changed = true;
      while (changed) {
        changed = false;
        edges.forEach(([a, b], e) => {
          if (!(mask & (1 << e))) return;
          if (comp[a] === count && comp[b] === -1) { comp[b] = count; changed = true; }
          if (comp[b] === count && comp[a] === -1) { comp[a] = count; changed = true; }
        });
      }
      count++;
    }
    const sums = new Array(count).fill(0);
    for (let v = 0; v < n; v++) sums[comp[v]] += values[v];
    if (sums.every(s => s % k === 0)) best = Math.max(best, count);
  }
  return best;
}

