function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 9);
  const pick = m => Math.floor(rand() * m);
  // Random tree shape: anything from a path to a star, built on positions and then relabelled.
  const shape = pick(4);
  const parent = [-1];
  for (let i = 1; i < n; i++) {
    if (shape === 0) parent.push(pick(i));
    else if (shape === 1) parent.push(i - 1);
    else if (shape === 2) parent.push(rand() < 0.7 ? 0 : pick(i));
    else parent.push(Math.max(0, i - 1 - pick(3)));
  }
  const label = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) { const j = pick(i + 1); [label[i], label[j]] = [label[j], label[i]]; }
  const edges = [];
  for (let i = 1; i < n; i++) edges.push(rand() < 0.5 ? [label[i], label[parent[i]]] : [label[parent[i]], label[i]]);
  for (let i = edges.length - 1; i > 0; i--) { const j = pick(i + 1); [edges[i], edges[j]] = [edges[j], edges[i]]; }
  const k = rand() < 0.6 ? 1 + pick(7) : 1 + pick(1000000000);
  const top = rand() < 0.5 ? 1000000000 : 3 * k;
  const vals = Array.from({ length: n }, () => (rand() < 0.15 ? 0 : pick(Math.min(top, 1000000000) + 1)));
  // Cut some edges on purpose and lower values until each planted part sums to a multiple of k.
  const cutChance = rand() * 0.5;
  const group = [0];
  for (let i = 1; i < n; i++) group.push(rand() < cutChance ? i : group[parent[i]]);
  const members = new Map();
  for (let i = 0; i < n; i++) { if (!members.has(group[i])) members.set(group[i], []); members.get(group[i]).push(i); }
  for (const list of members.values()) {
    let rest = list.reduce((s, i) => s + vals[i], 0) % k;
    for (const i of list) { const d = Math.min(vals[i], rest); vals[i] -= d; rest -= d; }
  }
  const values = new Array(n);
  for (let i = 0; i < n; i++) values[label[i]] = vals[i];
  return [n, edges, values, k];
}
